using System.Collections.Generic;using Alterverse.Profile;using UnityEngine;
namespace Alterverse.Audio
{
public enum DimensionSound{HitLight,HitHeavy,RecallStart,RecallComplete,RecallCancel,RealityShatter}
public sealed class DimensionAudio:MonoBehaviour
{
private static DimensionAudio instance;private readonly Dictionary<DimensionSound,AudioClip> clips=new();private AudioSource source;[RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]private static void AutoCreate(){if(FindAnyObjectByType<DimensionAudio>()==null)new GameObject("DF_Audio").AddComponent<DimensionAudio>();}private void Awake(){if(instance!=null&&instance!=this){Destroy(gameObject);return;}instance=this;source=gameObject.AddComponent<AudioSource>();source.playOnAwake=false;source.spatialBlend=0f;Build();}public static void Play(DimensionSound sound,float volume=1f,float pitch=1f){if(instance==null)return;instance.source.pitch=pitch;instance.source.PlayOneShot(instance.clips[sound],Mathf.Clamp01(volume)*PlayerProfile.MasterVolume*PlayerProfile.SfxVolume);instance.source.pitch=1f;}
private void Build(){clips[DimensionSound.HitLight]=Tone("DF_HitLight",.075f,980,180,.38f,true);clips[DimensionSound.HitHeavy]=Tone("DF_HitHeavy",.13f,220,70,.55f,true);clips[DimensionSound.RecallStart]=Tone("DF_RecallStart",.32f,180,520,.32f,false);clips[DimensionSound.RecallComplete]=Tone("DF_RecallComplete",.28f,430,1180,.42f,false);clips[DimensionSound.RecallCancel]=Tone("DF_RecallCancel",.14f,520,110,.30f,true);clips[DimensionSound.RealityShatter]=Tone("DF_RealityShatter",.42f,125,1450,.48f,true);}
private static AudioClip Tone(string name,float seconds,float startHz,float endHz,float gain,bool grit){int rate=22050,count=Mathf.Max(1,Mathf.RoundToInt(seconds*rate));float[] data=new float[count];uint noise=2463534242;for(int i=0;i<count;i++){float t=i/(float)count,hz=Mathf.Lerp(startHz,endHz,t),env=Mathf.Sin(Mathf.PI*t)*Mathf.Pow(1f-t,.35f),phase=2*Mathf.PI*hz*i/rate;float s=Mathf.Sin(phase)+.28f*Mathf.Sin(phase*2.01f);if(grit){noise^=noise<<13;noise^=noise>>17;noise^=noise<<5;s+=(((noise&65535)/32767.5f)-1f)*.18f;}data[i]=Mathf.Clamp(s*env*gain,-1,1);}AudioClip clip=AudioClip.Create(name,count,1,rate,false);clip.SetData(data,0);return clip;}private void OnDestroy(){foreach(AudioClip clip in clips.Values)if(clip!=null)Destroy(clip);clips.Clear();if(instance==this)instance=null;}
}
}
